  onu-00043 gpon  critica=True  cobravel=True
  onu-00044 xgs   critica=False cobravel=True
  onu-00045 xgs   critica=True  cobravel=False

hashavel (frozen): 1
asdict do ultimo : {'ident': 'onu-00045', 'potencia': -31.7, 'protocolo': &lt;Protocolo.XGS: 'xgs'&gt;, 'estado': &lt;Estado.SUSPENSA: 2&gt;, 'local': Coordenada(lat=-23.55, lon=-46.63), 'tags': ('prioridade',)}
